import re,json,collections
c={}
for l in open('commits.jsonl'):
    d=json.loads(l); c[d['txn']]=d
log=[l.split() for l in open('scheduler.log')]
# map txn -> job,run, task final state
runs=collections.defaultdict(list)
for p in log:
    runs[(p[1],p[2])].append(p)
stat=collections.Counter()
for k,v in runs.items():
    st=[x[3] for x in v if x[3].startswith('state=') and x[3]!='state=running']
    tx=[int(re.search(r'txn (\d+)',' '.join(x)).group(1)) for x in v if 'txn' in ' '.join(x)]
    for t in tx:
        stat[(k[0],tuple(st),c[t]['outcome'])]+=1
    if not tx: stat[(k[0],tuple(st),'notxn')]+=1
for k,v in sorted(stat.items()): print(k,v)
EOF

